using System.Collections;
using System.Collections.Generic;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SunnyFlaresAction", menuName = "Data/Battle/Battle Actions/Sothis/SunnyFlares Action")]
public class SunnyFlaresAction : BattleAction
{
	[Header("Effects")]
	[SerializeField]
	private ReliefDefaultEffectAction reliefDefaultEffectAction;

	[SerializeField]
	private int fixedRelief;

	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	[SerializeField]
	private float delayBetweenRelief;

	[Header("VFX")]
	[SerializeField]
	private float vfxDelay;

	public ReliefDefaultEffectAction ReliefDefaultEffectAction => reliefDefaultEffectAction;

	public int FixedRelief => fixedRelief;

	public override void CastAmount(int timesAmount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(DefaultCast(timesAmount, source));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
	}

	private IEnumerator DefaultCast(int timesAmount, GameObject source)
	{
		List<GameObject> list = currentActiveUnits.GetCurrentActiveUnits();
		List<GameObject> targetsPickedList = new List<GameObject>();
		for (int j = 0; j < timesAmount; j++)
		{
			targetsPickedList.Add(list.PickRandom());
		}
		yield return InvokeAlternatives.WaitOneFrame();
		if (IsVFXEnabled())
		{
			ReferenceSingleton<CoroutineHandler>.Instance.Run(VFXCoroutine(targetsPickedList));
			yield return new WaitForSeconds(vfxDelay);
		}
		for (int i = 0; i < targetsPickedList.Count; i++)
		{
			GameObject target = targetsPickedList[i];
			reliefDefaultEffectAction.CastTargetAmount(target, fixedRelief, source);
			yield return new WaitForSeconds(delayBetweenRelief);
		}
	}

	private IEnumerator VFXCoroutine(List<GameObject> targetsPickedList)
	{
		PlaySFX();
		for (int i = 0; i < targetsPickedList.Count; i++)
		{
			GameObject vFXOwner = targetsPickedList[i];
			SpawnVFX(GetVFXOwnerPosition(vFXOwner), 4f);
			yield return new WaitForSeconds(delayBetweenRelief);
		}
	}
}
